) VALUES (
    'johannes-lamparter-profile',
    '{"en": "Johannes Lamparter: Nordic Combined''s Rising Star", "de": "Johannes Lamparter: Aufgehender Stern der Nordischen Kombination", "fr": "Johannes Lamparter : L''étoile montante du combiné nordique", "it": "Johannes Lamparter: La stella nascente della combinata nordica", "es": "Johannes Lamparter: La estrella emergente de la combinada nórdica", "pt": "Johannes Lamparter: A estrela em ascensão do combinado nórdico", "nl": "Johannes Lamparter: Rijzende ster van de Noordse combinatie", "ar": "يوهانس لامبارتر: النجم الصاعد للجمع الشمالي", "ja": "ヨハネス・ランパーター：ノルディック複合の新星", "zh": "Johannes Lamparter: Beioufushi de Xinxing", "ko": "요하네스 람파터: 노르딕 복합의 떠오르는 스타"}'::jsonb,
    '{"en": "The young Austrian has emerged as a force in Nordic combined, excelling in both ski jumping and cross-country skiing. A future champion in the making.", "de": "Der junge Österreicher hat sich als Kraft in der Nordischen Kombination etabliert, hervorragend in Skisprung und Langlauf.", "fr": "Le jeune Autrichien s''est imposé comme une force dans le combiné nordique, excellant dans le saut à ski et le ski de fond.", "it": "Il giovane austriaco è emerso come forza nella combinata nordica, eccellendo sia nel salto con gli sci che nello sci di fondo.", "es": "El joven austriaco ha emergido como una fuerza en la combinada nórdica, destacando en salto de esquí y esquí de fondo.", "pt": "O jovem austríaco emergiu como uma força no combinado nórdico, destacando-se no salto de esqui e esqui cross-country.", "nl": "De jonge Oostenrijker is opgekomen als een kracht in de Noordse combinatie, uitblinkend in zowel schansspringen als langlaufen.", "ar": "برز النمساوي الشاب كقوة في الجمع الشمالي، متفوقاً في كل من القفز على الجليد والتزلج الريفي", "ja": "若いオーストリア人はノルディック複合で力として台頭し、スキージャンプとクロスカントリースキーの両方で優れています。", "zh": "Nianqing de Aodili ren yi chengwei beiou fushi zhong de liliang, zai huaxue tiaoyue he yueye huaxue fangmian dou biaoxian chuse.", "ko": "젊은 오스트리아인은 스키점프와 크로스컨트리 스키 모두에서 뛰어나며 노르딕 복합의 강자로 부상했습니다."}'::jsonb,
    '{"en": "<p>Johannes Lamparter represents the future of <a href=\"/nordic-combined-guide/\">Nordic combined</a>. The Austrian athlete has rapidly ascended to the top of the sport, challenging established champions with his exceptional abilities in both ski jumping and cross-country skiing.</p><h2>Two-Sport Excellence</h2><p>Nordic combined demands mastery of two very different disciplines. Athletes must excel at ski jumping - requiring explosive power and technical precision - and then immediately compete in a cross-country race requiring endurance and tactical racing skill.</p><p>Lamparter has shown he can compete with the best in both phases, giving him a significant advantage over specialists who may be stronger in only one discipline.</p><h2>Rapid Rise</h2><p>What sets Lamparter apart is how quickly he has reached the world elite. His progression from promising junior to World Cup contender happened faster than most experts predicted, suggesting his ceiling remains very high.</p><h2>Austrian Legacy</h2><p>Austria has produced many Nordic combined champions, and Lamparter carries that tradition forward. He represents a new generation ready to take over from established stars.</p><h2>Competition</h2><p>Lamparter battles against the legendary <a href=\"/jarl-magnus-riiber-profile/\">Jarl Magnus Riiber</a> and other top combined athletes. His willingness to attack in both disciplines makes every competition exciting.</p><h2>Future Prospects</h2><p>With his youth and already-proven abilities, Lamparter has the potential to dominate Nordic combined for years to come. Major championships remain his primary focus as he seeks to convert regular-season success into championship gold.</p>", "de": "<p>Johannes Lamparter repräsentiert die Zukunft der <a href=\"/nordic-combined-guide/\">Nordischen Kombination</a>. Der österreichische Athlet ist schnell an die Spitze des Sports aufgestiegen.</p><h2>Exzellenz in zwei Sportarten</h2><p>Die Nordische Kombination erfordert die Beherrschung zweier sehr unterschiedlicher Disziplinen. Athleten müssen im Skisprung brillieren und dann sofort ein Langlaufrennen bestreiten.</p><h2>Schneller Aufstieg</h2><p>Was Lamparter auszeichnet, ist wie schnell er die Weltelite erreicht hat.</p><h2>Österreichisches Erbe</h2><p>Österreich hat viele Kombinations-Champions hervorgebracht, und Lamparter führt diese Tradition fort.</p><h2>Konkurrenz</h2><p>Er kämpft gegen den legendären <a href=\"/jarl-magnus-riiber-profile/\">Jarl Magnus Riiber</a>.</p>", "fr": "<p>Johannes Lamparter représente l''avenir du <a href=\"/nordic-combined-guide/\">combiné nordique</a>. L''athlète autrichien a rapidement gravi les échelons du sport.</p><h2>Excellence dans deux sports</h2><p>Le combiné nordique exige la maîtrise de deux disciplines très différentes. Les athlètes doivent exceller en saut à ski puis immédiatement concourir en ski de fond.</p><h2>Ascension rapide</h2><p>Ce qui distingue Lamparter, c''est la rapidité avec laquelle il a atteint l''élite mondiale.</p><h2>Héritage autrichien</h2><p>L''Autriche a produit de nombreux champions du combiné nordique.</p><h2>Concurrence</h2><p>Il affronte le légendaire <a href=\"/jarl-magnus-riiber-profile/\">Jarl Magnus Riiber</a>.</p>", "it": "<p>Johannes Lamparter rappresenta il futuro della <a href=\"/nordic-combined-guide/\">combinata nordica</a>. L''atleta austriaco è rapidamente salito ai vertici dello sport.</p><h2>Eccellenza in due sport</h2><p>La combinata nordica richiede la padronanza di due discipline molto diverse. Gli atleti devono eccellere nel salto con gli sci e poi competere immediatamente nel fondo.</p><h2>Ascesa rapida</h2><p>Ciò che distingue Lamparter è la velocità con cui ha raggiunto l''élite mondiale.</p><h2>Eredità austriaca</h2><p>L''Austria ha prodotto molti campioni della combinata nordica.</p>", "es": "<p>Johannes Lamparter representa el futuro de la <a href=\"/nordic-combined-guide/\">combinada nórdica</a>. El atleta austriaco ha ascendido rápidamente a la cima del deporte.</p><h2>Excelencia en dos deportes</h2><p>La combinada nórdica exige dominio de dos disciplinas muy diferentes.</p><h2>Ascenso rápido</h2><p>Lo que distingue a Lamparter es la rapidez con que alcanzó la élite mundial.</p>", "pt": "<p>Johannes Lamparter representa o futuro do <a href=\"/nordic-combined-guide/\">combinado nórdico</a>. O atleta austríaco ascendeu rapidamente ao topo do esporte.</p><h2>Excelência em dois esportes</h2><p>O combinado nórdico exige domínio de duas disciplinas muito diferentes.</p><h2>Ascensão rápida</h2><p>O que distingue Lamparter é a rapidez com que alcançou a elite mundial.</p>", "nl": "<p>Johannes Lamparter vertegenwoordigt de toekomst van de <a href=\"/nordic-combined-guide/\">Noordse combinatie</a>. De Oostenrijkse atleet is snel naar de top van de sport gestegen.</p><h2>Excellentie in twee sporten</h2><p>De Noordse combinatie vereist beheersing van twee zeer verschillende disciplines.</p><h2>Snelle opkomst</h2><p>Wat Lamparter onderscheidt is hoe snel hij de wereldelite heeft bereikt.</p>", "ar": "<p>يمثل يوهانس لامبارتر مستقبل <a href=\"/nordic-combined-guide/\">الجمع الشمالي</a>. صعد الرياضي النمساوي بسرعة إلى قمة الرياضة.</p><h2>التميز في رياضتين</h2><p>يتطلب الجمع الشمالي إتقان تخصصين مختلفين تماماً.</p><h2>الصعود السريع</h2><p>ما يميز لامبارتر هو السرعة التي وصل بها إلى النخبة العالمية.</p>", "ja": "<p>ヨハネス・ランパーターは<a href=\"/nordic-combined-guide/\">ノルディック複合</a>の未来を代表しています。オーストリアの選手は急速にスポーツのトップに上り詰めました。</p><h2>2つのスポーツでの卓越性</h2><p>ノルディック複合は、2つの非常に異なる種目のマスターを要求します。</p><h2>急速な台頭</h2><p>ランパーターを際立たせているのは、彼が世界のエリートに到達した速さです。</p>", "zh": "<p>Johannes Lamparter daibiao <a href=\"/nordic-combined-guide/\">beiou fushi</a> de weilai. Aodili yundongyuan xunsu shengzhi yundong de dingfeng.</p><h2>Liang xiang yundong de zhuoyue</h2><p>Beiou fushi yaoqiu zhangwo liang ge feichangbutong de xiangmu.</p><h2>Xunsu jueqi</h2><p>Lamparter de tuchu zhichu shi ta duome kuai de dadao shijie jingying.</p>", "ko": "<p>요하네스 람파터는 <a href=\"/nordic-combined-guide/\">노르딕 복합</a>의 미래를 대표합니다. 오스트리아 선수는 빠르게 스포츠의 정상에 올랐습니다.</p><h2>두 스포츠에서의 탁월함</h2><p>노르딕 복합은 두 가지 매우 다른 종목의 숙달을 요구합니다.</p><h2>빠른 상승</h2><p>람파터를 돋보이게 하는 것은 그가 세계 엘리트에 도달한 속도입니다.</p>"}'::jsonb,
    'athlete-profile',
